/// The `HTMLVideoElement` constructor (`[HTMLConstructor]`).
fn ctor_callback<D: Dom>(
    scope: &mut v8::PinScope,
    args: v8::FunctionCallbackArguments,
    mut rv: v8::ReturnValue,
) {
    let _prof = rt::prof::enter(scope, "new HTMLVideoElement");
    if !args.is_construct_call() {
        return rt::throw_type_error(
            scope,
            "Failed to construct 'HTMLVideoElement': Please use the 'new' operator",
        );
    }
    let Ok(nt) = v8::Local::<v8::Object>::try_from(args.new_target()) else {
        return;
    };
    let nt = JsObject(v8::Global::new(scope, nt));
    let st = rt::state(scope);
    let dom = st.engine::<D>();
    let r = {
        let mut cx = Cx::new(scope);
        <D as rt::Host>::html_constructor(dom, &mut cx, InterfaceId::HTMLVideoElement, &nt)
    };
    let Some(h) = rt::check(scope, r) else { return };
    let Some(w) = rt::wrap(scope, h) else { return };
    rv.set(w.into());
}

